def perform_arithmetic(operation, num1, num2):
    """Perform a basic arithmetic operation based on user input."""
    if operation == '+':
        result = num1 + num2
    elif operation == '-':
        result = num1 - num2
    elif operation == '*':
        result = num1 * num2
    elif operation == '/':
        if num2 == 0:
            raise ValueError("Cannot divide by zero.")
        result = num1 / num2
    else:
        raise ValueError(f"Invalid operation: {operation}. Please use +, -, *, or /.")

    return result


