            user_input = input("Enter an arithmetic operation (e.g., 10 + 5): ")
            operation, num1_str, num2_str = user_input.split()
            num1 = float(num1_str)
            num2 = float(num2_str)
            result = perform_arithmetic(operation, num1, num2)
            print(f"{num1} {operation} {num2} = {result}")
        except ValueError as e:
            print(e)
        except Exception as e:
            print(f"An unexpected error occurred: {e}. Please try again.")
        finally:
            print("Do you want to perform another operation? (yes/no): ")
            user_input = input().lower()
            if user_input != "yes":
                break
